const idade = 20;
const estado = idade >= 18 ? "adulto" : "menor";
console.log(estado); // "adulto"

// Como é uma expressão, pode usar-se diretamente num template literal
const saudacao = (hora) => `Boa ${hora < 12 ? "manhã" : "tarde"}!`;
console.log(saudacao(9));  // "Boa manhã!"
console.log(saudacao(15)); // "Boa tarde!"

const nota = 72;

// Vários ternários encadeados, um por linha: ainda legível com boa formatação
const classificacao =
  nota >= 90 ? "Excelente" :
  nota >= 70 ? "Bom" :
  nota >= 50 ? "Suficiente" :
  "Insuficiente";

console.log(classificacao); // "Bom"

function saudar(nome) {
  const nomeFinal = nome || "visitante";
  console.log(`Olá, ${nomeFinal}!`);
}

saudar("Ana"); // "Olá, Ana!"
saudar("");    // "Olá, visitante!" (string vazia é falsy)

// Antes de existir o optional chaining (?.), && encadeado evitava
// erros ao aceder a propriedades de objetos que podiam não existir
const utilizador = { endereco: { cidade: "Porto" } };
const cidade = utilizador && utilizador.endereco && utilizador.endereco.cidade;
console.log(cidade); // "Porto"

const semEndereco = { nome: "Rui" };
const cidade2 = semEndereco && semEndereco.endereco && semEndereco.endereco.cidade;
console.log(cidade2); // undefined (não rebenta, mesmo sem endereco)

function criarConfig(opcoes = {}) {
  return {
    volume: opcoes.volume ?? 50,
    tema: opcoes.tema ?? "claro",
  };
}

console.log(criarConfig({ volume: 0 }));
// { volume: 0, tema: "claro" } — o 0 é respeitado

const config = { limite: 0 };
console.log(config.limite || 10); // 10 (errado: queríamos manter o 0)
console.log(config.limite ?? 10); // 0 (correto)

function processarPedido(pedido) {
  if (!pedido) return null;               // guard clause: sem pedido, não continua
  if (!pedido.itens?.length) return null;  // guard clause: sem itens, não continua

  const total = pedido.itens.reduce((soma, item) => soma + item.preco, 0);
  return { ...pedido, total };
}

// Combinar curto-circuito com early return evita "pirâmides" de ifs aninhados
function calcularDesconto(cliente) {
  if (!cliente?.ativo) return 0;
  if (cliente.pontos < 100) return 0;

  return cliente.pontos >= 500 ? 0.2 : 0.1;
}

