function classificarParidade(numero) {
  return numero % 2 === 0 ? "par" : "ímpar";
}

console.log(classificarParidade(7));  // "ímpar"
console.log(classificarParidade(10)); // "par"

function criarTemporizador(opcoes = {}) {
  const duracao = opcoes.duracao ?? 60;
  const avisoSonoro = opcoes.avisoSonoro ?? true;

  return { duracao, avisoSonoro };
}

console.log(criarTemporizador({ duracao: 0 }));
// { duracao: 0, avisoSonoro: true }
console.log(criarTemporizador({}));
// { duracao: 60, avisoSonoro: true }
console.log(criarTemporizador({ avisoSonoro: false }));
// { duracao: 60, avisoSonoro: false }

exercises.statement:
Tem a seguinte função escrita com ifs aninhados:

function registar(utilizador) {
  if (utilizador) {
    if (utilizador.email) {
      if (utilizador.idade >= 18) {
        return { sucesso: true, mensagem: "Registo aceite" };
      } else {
        return { sucesso: false, mensagem: "Idade insuficiente" };
      }
    } else {
      return { sucesso: false, mensagem: "Email em falta" };
    }
  } else {
    return { sucesso: false, mensagem: "Utilizador em falta" };
  }
}

Reescreva-a usando guard clauses (early return) para eliminar o aninhamento, mantendo exatamente o mesmo comportamento para os mesmos argumentos.

exercises.solution_code:
function registar(utilizador) {
  if (!utilizador) return { sucesso: false, mensagem: "Utilizador em falta" };
  if (!utilizador.email) return { sucesso: false, mensagem: "Email em falta" };
  if (!(utilizador.idade >= 18)) return { sucesso: false, mensagem: "Idade insuficiente" };

  return { sucesso: true, mensagem: "Registo aceite" };
}

function calcularPreco(produto, cliente) {
  if (!produto || !(produto.preco > 0)) return null;

  const temPromocao = typeof produto.promocao === "number" && produto.promocao > 0 && produto.promocao < 1;
  const precoComPromocao = temPromocao ? produto.preco * (1 - produto.promocao) : produto.preco;

  const ehVip = cliente?.vip ?? false;
  const temCupao = !ehVip && Boolean(cliente?.cupao);

  const precoComDescontoCliente = ehVip
    ? precoComPromocao * 0.9
    : temCupao
      ? precoComPromocao * 0.95
      : precoComPromocao;

  return Math.round(precoComDescontoCliente * 100) / 100;
}

console.log(calcularPreco({ preco: 100, promocao: 0.2 }, { vip: true }));
// 72
console.log(calcularPreco({ preco: 50 }, { cupao: "PROMO5" }));
// 47.5
console.log(calcularPreco(null, { vip: true }));
// null
